css:
/* Modales (Login & Perfil B2B) */
.saas-modal-overlay { position: fixed; inset: 0; background: rgba(10, 34, 64, 0.6); backdrop-filter: blur(5px); z-index: 3000; display: flex; align-items: center; justify-content: center; padding: 20px; opacity: 1; transition: opacity 0.3s ease; }
.saas-modal-overlay.hidden { opacity: 0; pointer-events: none; }
.saas-modal-card { background: #FFFFFF; width: 100%; max-width: 440px; border-radius: 24px; padding: 40px; box-shadow: 0 25px 50px -12px rgba(0,0,0,0.25); position: relative; transform: translateY(0); transition: transform 0.4s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid #E2E8F0; }
.saas-modal-overlay.hidden .saas-modal-card { transform: translateY(30px); }

.close-modal-btn { position: absolute; top: 20px; right: 20px; background: transparent; border: none; font-size: 1.8rem; color: #94a3b8; cursor: pointer; transition: color 0.2s; line-height: 1; width: 30px; height: 30px; display: flex; align-items: center; justify-content: center; border-radius: 50%; }
.close-modal-btn:hover { color: #A81200; background: #fef2f2; }

/* Login Modal */
.modal-header-center { text-align: center; margin-bottom: 20px; }
.modal-logo-clean { height: 75px; margin-bottom: 15px; object-fit: contain; }
.modal-header-center h2 { font-size: 1.8rem; font-weight: 900; color: #0A2240; margin-bottom: 10px; letter-spacing: -0.5px; }
.modal-header-center p { font-size: 0.95rem; color: #64748B; line-height: 1.5; }
.secure-badge { display: flex; justify-content: center; align-items: center; gap: 6px; margin-top: 25px; font-size: 0.8rem; color: #94a3b8; font-weight: 600; }
.secure-badge svg { width: 14px; height: 14px; }

/* Perfil B2B Modal */
.profile-card { max-width: 480px; padding: 0; overflow: hidden;}
.profile-header { background: #f8fafc; padding: 30px; display: flex; align-items: center; gap: 20px; border-bottom: 1px solid #E2E8F0; }
.profile-avatar-img { width: 64px; height: 64px; border-radius: 50%; object-fit: cover; box-shadow: 0 4px 10px rgba(10,34,64,0.1); border: 2px solid #FFFFFF; background: #E2E8F0;}
.profile-info h2 { font-size: 1.25rem; font-weight: 800; color: #0F172A; margin-bottom: 2px; line-height: 1.2; word-break: break-word;}
.user-email { font-size: 0.9rem; color: #64748b; font-weight: 500; }

.reorder-section { padding: 30px; }
.reorder-header { display: flex; justify-content: space-between; align-items: center; margin-bottom: 15px; }
.reorder-header h3 { font-size: 1.05rem; font-weight: 800; color: #0A2240; text-transform: uppercase; }

.order-list-preview { background: #f8fafc; border: 1px solid #E2E8F0; border-radius: 12px; padding: 15px 20px; margin-bottom: 25px; }
.order-list-preview ul { list-style: none; display: flex; flex-direction: column; gap: 8px; padding: 0; margin: 0; }
.order-list-preview li { display: flex; align-items: center; gap: 8px; font-size: 0.95rem; color: #0F172A; font-weight: 500; }
.order-list-preview li svg { width: 16px; color: #10b981; }

.logout-wrapper { padding: 0 30px 25px; display: flex; justify-content: center; }
.btn-logout { background: transparent; border: none; color: #94a3b8; font-size: 0.9rem; font-weight: 600; cursor: pointer; text-decoration: underline; transition: color 0.2s;}
.btn-logout:hover { color: #A81200; }

/* Icono Navbar Logueado Global */
.icon-btn.logged-in { border-color: #25D366 !important; background: rgba(37, 211, 102, 0.1) !important; position: relative; }
.icon-btn.logged-in::after { content: ''; position: absolute; top: 0px; right: 0px; width: 12px; height: 12px; background: #25D366; border-radius: 50%; border: 2px solid #16365C; z-index: 2;}
.nav-user-avatar { width: 100%; height: 100%; object-fit: cover; border-radius: 50%; display: none; }
.icon-btn.logged-in .nav-user-avatar { display: block; }
.icon-btn.logged-in svg { display: none; }

/* Toasts Globales */
.toast-container { position: fixed; bottom: 100px; left: 50%; transform: translateX(-50%); z-index: 3000; display: flex; flex-direction: column; gap: 10px; pointer-events: none; }
.toast { background: rgba(10, 34, 64, 0.95); backdrop-filter: blur(10px); color: #FFFFFF; padding: 14px 28px; border-radius: 50px; font-size: 0.95rem; font-weight: 600; box-shadow: 0 10px 30px rgba(0,0,0,0.3); display: flex; align-items: center; gap: 12px; animation: toastSlideUp 0.3s ease forwards; border: 1px solid rgba(255,255,255,0.1); }
.toast svg { width: 20px; color: #25D366; }
.toast.fade-out { animation: toastFadeOut 0.4s ease forwards; }
@keyframes toastSlideUp { from { opacity: 0; transform: translateY(30px) scale(0.9); } to { opacity: 1; transform: translateY(0) scale(1); } }
@keyframes toastFadeOut { to { opacity: 0; transform: translateY(-15px) scale(0.9); } }


/* =========================================
   1. VARIABLES Y BASE 
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-blue-light: #16365C; 
    --zarco-blue-glass: rgba(10, 34, 64, 0.95); 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --wa-green-dark: #1DA851;

    --bg-light: #F8FAFC; /* Fondo global levísimamente gris para que el blanco de las tarjetas resalte */
    --border-soft: #E2E8F0;
    --text-main: #0F172A;
    --text-muted: #64748B;

    --transition-fast: 0.3s cubic-bezier(0.4, 0, 0.2, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }

html { scroll-behavior: smooth; }
body { overflow-x: hidden; width: 100%; font-family: 'Inter', sans-serif; color: var(--text-main); background-color: var(--bg-light); line-height: 1.6; }

section[id] { scroll-margin-top: 120px; }

.nav-container { width: 90%; max-width: 1400px; margin: 0 auto; position: relative; }
.desktop-only { display: block; } .mobile-only { display: none; }
.text-red { color: var(--zarco-red) !important; }
.text-center { text-align: center !important; }

/* REVEAL ENGINE FLUIDO */
.reveal-up { opacity: 0; transform: translateY(30px); transition: opacity 1s var(--expo), transform 1s var(--expo); will-change: opacity, transform; }
.reveal-up.active { opacity: 1; transform: translateY(0); }
.reveal { opacity: 0; transform: translateY(20px); transition: opacity 0.8s ease, transform 0.8s ease; }
.reveal.active { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 

.btn-primary { background-color: var(--zarco-red); color: var(--white); border: none; padding: 16px 36px; font-weight: 900; font-size: 0.9rem; text-transform: uppercase; letter-spacing: 2px; cursor: pointer; border-radius: 8px; transition: all var(--transition-fast); position: relative; overflow: hidden; display: inline-flex; align-items: center; justify-content: center; gap: 8px; box-shadow: 0 10px 25px rgba(168, 18, 0, 0.25); }
.btn-primary::before { content: ''; position: absolute; top: 0; left: -100%; width: 50%; height: 100%; background: linear-gradient(to right, rgba(255,255,255,0) 0%, rgba(255,255,255,0.3) 50%, rgba(255,255,255,0) 100%); transform: skewX(-25deg); transition: left 0.6s ease-in-out; }
.btn-primary:hover { transform: translateY(-4px); box-shadow: 0 15px 35px rgba(168, 18, 0, 0.4); background-color: #ba1400; }
.btn-primary:hover::before { left: 200%; }

/* =========================================
   2. HERO SECTOR Y NAVEGACIÓN ESTÁTICA
   ========================================= */
.sector-page-wrapper { padding-top: 180px; padding-bottom: 80px; position: relative;}

.wholesale-hero { padding: 40px 0 60px; background-color: var(--bg-light); text-align: center; position: relative; z-index: 10;}
.hero-clean-content { max-width: 900px; margin: 0 auto; display: flex; flex-direction: column; align-items: center; padding: 0 5%;}

.hero-badge-simple { display: inline-block; background: rgba(168,18,0,0.05); color: var(--zarco-red); font-size: 0.85rem; font-weight: 900; letter-spacing: 3px; padding: 10px 22px; border-radius: 50px; margin-bottom: 30px; border: 1px solid rgba(168,18,0,0.1); text-transform: uppercase; }
.hero-title-clean { font-size: clamp(2.8rem, 4.5vw, 4.5rem); font-weight: 900; line-height: 1.1; color: var(--zarco-blue); margin-bottom: 24px; letter-spacing: -1.5px; text-transform: uppercase;}
.hero-desc-clean { font-size: 1.25rem; color: var(--text-muted); line-height: 1.6; margin-bottom: 45px; max-width: 750px; }
.hero-desc-clean strong { color: var(--zarco-blue); font-weight: 800; }
.hero-buttons { display: flex; gap: 15px; justify-content: center; flex-wrap: wrap; }

/* SUBNAV ESTÁTICO */
.sector-subnav { background: var(--white); border-bottom: 1px solid var(--border-soft); padding: 25px 0; margin-bottom: 50px; box-shadow: 0 4px 20px rgba(0,0,0,0.02); }
.subnav-links { display: flex; justify-content: center; gap: 50px; list-style: none; margin: 0; padding: 0; }
.subnav-links a { text-decoration: none; color: var(--text-muted); font-weight: 800; font-size: 1rem; text-transform: uppercase; letter-spacing: 1px; padding: 8px 4px; transition: all 0.3s ease; position: relative; }
.subnav-links a:hover { color: var(--zarco-blue); }
.subnav-links a::after { content: ''; position: absolute; bottom: -6px; left: 0; width: 100%; height: 3px; background: var(--zarco-red); transform: scaleX(0); transition: transform 0.3s ease; transform-origin: center; }
.subnav-links a:hover::after { transform: scaleX(1); }

/* =========================================
   3. SHOWROOM CARRUSELES ESTÉTICA 100X
   ========================================= */
.carousel-section { max-width: 1400px; margin: 90px auto; padding: 0 5%; }
.carousel-header { display: flex; justify-content: space-between; align-items: flex-end; margin-bottom: 40px; }
.carousel-header h2 { font-size: 2.6rem; font-weight: 900; color: var(--zarco-blue); letter-spacing: -1px; line-height: 1.1; margin: 0;}

.carousel-nav { display: flex !important; flex-direction: row !important; gap: 15px !important; align-items: center; justify-content: flex-end; flex-wrap: nowrap; min-width: 120px;}
.arrow-btn { width: 54px !important; height: 54px !important; border-radius: 50% !important; border: 2px solid #E2E8F0; background: var(--white); color: var(--zarco-blue); display: flex !important; align-items: center !important; justify-content: center !important; cursor: pointer; transition: all var(--transition-fast); box-shadow: 0 4px 10px rgba(0,0,0,0.03); flex-shrink: 0 !important; }
.arrow-btn svg { width: 24px; height: 24px; stroke-width: 2.5; }
.arrow-btn:hover { border-color: var(--zarco-blue); background: var(--zarco-blue); color: var(--white); box-shadow: 0 10px 25px rgba(10,34,64,0.2); transform: scale(1.08);}

.carousel-track {
    display: flex;
    gap: 30px; 
    overflow-x: auto;
    padding: 20px 20px 60px 20px; 
    margin: -20px -20px -40px -20px;
    -ms-overflow-style: none;  
    scrollbar-width: none;     
    scroll-behavior: smooth;
    scroll-snap-type: x mandatory;
}
.carousel-track::-webkit-scrollbar { display: none; }

/* TARJETAS TITÁN */
.product-card {
    flex: 0 0 320px; 
    background: var(--white);
    border: 1px solid rgba(226, 232, 240, 0.8);
    border-radius: 24px; 
    overflow: hidden;
    scroll-snap-align: start; 
    transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
    display: flex;
    flex-direction: column;
    box-shadow: 0 10px 30px -10px rgba(10,34,64,0.08); 
    cursor: pointer; 
}
.product-card:hover {
    transform: translateY(-12px);
    box-shadow: 0 30px 60px -15px rgba(10,34,64,0.18); 
    border-color: rgba(168, 18, 0, 0.15); 
}

/* CAJA DE IMAGEN CON SPOTLIGHT */
.product-image-box {
    width: 100%;
    height: 250px; 
    background: radial-gradient(circle at center, #ffffff 0%, #f1f5f9 100%); 
    position: relative;
    display: flex;
    align-items: center;
    justify-content: center;
    border-bottom: 1px solid var(--border-soft);
    overflow: hidden;
    padding: 25px; 
}

/* ETIQUETA UNITARIA ALTA GAMA */
.product-unit {
    position: absolute; 
    top: 16px; 
    right: 16px; 
    background: var(--zarco-blue); 
    color: var(--white); 
    padding: 6px 14px; 
    border-radius: 8px; 
    font-size: 0.75rem; 
    font-weight: 900; 
    letter-spacing: 1.5px; 
    box-shadow: 0 4px 15px rgba(10,34,64,0.3); 
    z-index: 3;
    text-transform: uppercase;
}

.product-info { padding: 30px 25px; display: flex; flex-direction: column; flex-grow: 1; }

.product-name { font-size: 1.25rem; font-weight: 900; color: var(--text-main); margin-bottom: 12px; line-height: 1.35; transition: color 0.3s ease; min-height: 55px; letter-spacing: -0.5px;}
.product-card:hover .product-name { color: var(--zarco-red); }

/* MARCA ESTILO BADGE */
.product-brand { 
    color: var(--zarco-blue); 
    font-size: 0.75rem; 
    font-weight: 800; 
    margin-bottom: 25px; 
    flex-grow: 1; 
    text-transform: uppercase; 
    letter-spacing: 2px;
    background: #F1F5F9; 
    padding: 6px 12px;
    border-radius: 6px;
    align-self: flex-start; 
}

.product-price-row { display: flex; justify-content: space-between; align-items: center; border-top: 1px dashed #CBD5E1; padding-top: 20px; margin-bottom: 20px;}
.price-label { font-size: 0.8rem; color: var(--text-muted); font-weight: 800; text-transform: uppercase; letter-spacing: 1px; display: flex; align-items: center;}
.cov-dot { width: 8px; height: 8px; background: var(--wa-green); border-radius: 50%; box-shadow: 0 0 0 3px rgba(37, 211, 102, 0.2); margin-right: 8px;}
.status-available { font-size: 0.8rem; font-weight: 900; color: #059669; background: #ecfdf5; padding: 6px 12px; border-radius: 6px; border: 1px solid #a7f3d0;}

/* CTA DE TARJETA MEJORADO */
.view-all-container { margin-top: auto; display: flex; align-items: center;}
.btn-view-catalog { display: block; color: var(--zarco-blue); font-weight: 800; font-size: 0.95rem; text-decoration: none; padding-top: 5px; transition: all 0.3s ease; width: 100%;}
.product-card:hover .btn-view-catalog { color: var(--zarco-red); transform: translateX(5px); }


/* =========================================
   4. SECCIÓN BENEFICIOS B2B
   ========================================= */
.benefits-section { padding: 100px 0; background-color: var(--white); }
.section-header { text-align: center; margin-bottom: 70px; }
.section-header h2 { color: var(--zarco-blue); font-size: 2.8rem; font-weight: 900; letter-spacing: -1px; text-transform: uppercase; }

.benefits-container { display: grid; grid-template-columns: repeat(3, 1fr); gap: 40px; max-width: 1200px; margin: 0 auto; padding: 0 5%;}
.benefit-item { display: flex; flex-direction: column; align-items: flex-start; text-align: left; padding: 50px 40px; background: var(--white); border-radius: 24px; transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1); border: 1px solid var(--border-soft); position: relative; overflow: hidden; box-shadow: 0 10px 30px -10px rgba(10,34,64,0.05);}

.benefit-item::before { content: ''; position: absolute; top: 0; left: 0; width: 100%; height: 6px; background: var(--zarco-red); transform: scaleX(0); transition: transform 0.5s ease; transform-origin: left; }
.benefit-item:hover::before { transform: scaleX(1); }
.benefit-item:hover { transform: translateY(-10px); box-shadow: 0 30px 60px -15px rgba(10,34,64,0.12); border-color: transparent; }

.benefit-icon { width: 70px; height: 70px; background: rgba(168,18,0,0.05); color: var(--zarco-red); border-radius: 16px; display: flex; align-items: center; justify-content: center; margin-bottom: 30px; }
.benefit-icon svg { width: 32px; height: 32px; stroke-width: 2.5px;}
.benefit-text h3 { color: var(--zarco-blue); font-size: 1.4rem; font-weight: 900; margin-bottom: 15px; letter-spacing: -0.5px;}
.benefit-text p { color: var(--text-muted); font-size: 1.1rem; line-height: 1.7; margin: 0; }

/* =========================================
   5. BANNER CTA FINAL
   ========================================= */
.niche-cta-banner { background: var(--white); border: 1px solid var(--border-soft); border-radius: 32px; padding: 80px 50px; text-align: center; max-width: 1000px; margin: 0 auto 100px; box-shadow: 0 30px 60px -15px rgba(10,34,64,0.08); position: relative; overflow: hidden;}
.niche-cta-banner::before { content: ''; position: absolute; top: -50%; left: -50%; width: 200%; height: 200%; background: radial-gradient(circle, rgba(168,18,0,0.03) 0%, rgba(255,255,255,0) 70%); z-index: 0; pointer-events: none;}

.niche-cta-content { display: flex; flex-direction: column; align-items: center; position: relative; z-index: 1;}
.niche-cta-content h2 { font-size: 2.8rem; font-weight: 900; color: var(--zarco-blue); margin-bottom: 20px; letter-spacing: -1.5px; }
.niche-cta-content p { font-size: 1.25rem; color: var(--text-muted); margin-bottom: 45px; max-width: 650px; font-weight: 500; line-height: 1.6;}

.btn-whatsapp-submit { 
    background: linear-gradient(135deg, var(--wa-green) 0%, var(--wa-green-dark) 100%);
    color: var(--white); 
    padding: 18px 45px; 
    font-size: 1.1rem; 
    font-weight: 900; 
    border-radius: 14px; 
    text-decoration: none;
    display: inline-flex; 
    align-items: center; 
    justify-content: center; 
    gap: 12px; 
    transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1); 
    box-shadow: 0 10px 25px rgba(37, 211, 102, 0.3), inset 0 -3px 0 rgba(0,0,0,0.15); 
    letter-spacing: 0.5px;
}
.btn-whatsapp-submit svg { width: 26px; height: 26px; fill: currentColor; transition: transform 0.3s ease;}
.btn-whatsapp-submit:hover { transform: translateY(-4px); box-shadow: 0 15px 35px rgba(37, 211, 102, 0.4), inset 0 -3px 0 rgba(0,0,0,0.15); }
.btn-whatsapp-submit:hover svg { transform: scale(1.15) rotate(-5deg); }

/* Botón flotante de WhatsApp global */
.whatsapp-float { position: fixed; bottom: 40px; right: 40px; background-color: var(--wa-green); color: var(--white); display: flex; align-items: center; gap: 12px; padding: 14px 28px; border-radius: 50px; text-decoration: none; font-weight: 800; font-size: 0.95rem; letter-spacing: 1px; box-shadow: 0 10px 30px rgba(37, 211, 102, 0.4); z-index: 1999; transition: all 0.4s cubic-bezier(0.16, 1, 0.3, 1); }
.whatsapp-float svg { width: 24px; height: 24px; fill: currentColor; }
.whatsapp-float:hover { transform: translateY(-6px); box-shadow: 0 15px 40px rgba(37, 211, 102, 0.5); background-color: #20BA56; }


/* =========================================
   6. RESPONSIVIDAD MÓVIL BLINDADA
   ========================================= */
@media (max-width: 1024px) {
    .sector-page-wrapper { padding-top: 140px; padding-bottom: 50px; }

    .hero-title-clean { font-size: 2.4rem; letter-spacing: -1px; }
    .hero-desc-clean { font-size: 1.1rem; }

    .sector-subnav { padding: 15px 0; margin-bottom: 40px;}
    .subnav-links { justify-content: space-between; gap: 5px; padding: 0 2%; }
    .subnav-links a { font-size: 0.75rem; letter-spacing: 0.5px; padding: 6px 0; display: block; text-align: center;}

    .carousel-section { margin: 60px auto; }
    .carousel-header { flex-direction: column; align-items: flex-start; gap: 20px;}
    .carousel-header h2 { font-size: 2rem; }

    .carousel-nav { align-self: flex-end; } 

    .carousel-track { gap: 20px; padding-bottom: 40px; } 
    .product-card { flex: 0 0 280px; } 
    .product-info { padding: 25px 20px; }
    .product-image-box { height: 220px; padding: 15px;}

    .benefits-section { padding: 60px 0; }
    .section-header h2 { font-size: 2rem; }
    .benefits-container { grid-template-columns: 1fr; gap: 25px; }
    .benefit-item { padding: 35px 25px; align-items: center; text-align: center; }

    .niche-cta-banner { padding: 50px 20px; margin: 0 5% 60px; border-radius: 24px;}
    .niche-cta-content h2 { font-size: 2rem; }
    .niche-cta-content p { font-size: 1.05rem; }
    .btn-whatsapp-submit { width: 100%; padding: 18px 20px; font-size: 1rem; }

    .whatsapp-float { bottom: 20px; right: 20px; padding: 12px 20px; font-size: 0.85rem; }
    .whatsapp-float span { display: none; }
}


  :root {
    --zarco-blue: #0A2240;
    --zarco-blue-light: #16365C;
    --zarco-blue-glass: rgba(10,34,64,0.95);
    --zarco-red: #A81200;
    --white: #FFFFFF;
    --wa-green: #10B981;
    --transition-fast: 0.3s cubic-bezier(0.16,1,0.3,1);
    --shadow-pop: 0 15px 35px -5px rgba(10,34,64,0.15),0 5px 15px rgba(0,0,0,0.05)
  }
  .desktop-only { display: block }
  .mobile-only { display: none }
  .navbar {
    position: fixed;
    top: 0;
    width: 100%;
    z-index: 2000;
    transition: transform .6s var(--transition-fast),box-shadow .6s var(--transition-fast);
    box-shadow: 0 4px 20px rgba(0,0,0,.15);
    font-family: 'Inter',sans-serif
  }
  .navbar.nav-hidden { transform: translateY(-100%) }
  .nav-container {
    width: 90%;
    max-width: 1400px;
    margin: 0 auto;
    position: relative
  }
  .nav-top {
    background-color: var(--zarco-blue-light);
    padding: 20px 0;
    transition: padding var(--transition-fast)
  }
  .top-container {
    display: grid;
    grid-template-columns: 1fr auto 1fr;
    align-items: center;
    max-width: 1200px;
    margin: 0 auto
  }
  .nav-left { justify-self: start }
  .nav-center { justify-self: center }
  .nav-right {
    justify-self: end;
    display: flex;
    align-items: center;
    gap: 15px
  }
  .nav-logo img {
    height: 100px;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.3));
    transition: height var(--transition-fast);
    display: block
  }
  .nav-logo img:hover { transform: scale(1.03) }
  .nav-gif {
    height: 100px;
    object-fit: contain;
    border-radius: 8px;
    display: block;
    filter: drop-shadow(0 4px 10px rgba(0,0,0,.2))
  }
  .btn-primary {
    background-color: var(--zarco-red);
    color: var(--white);
    border: none;
    padding: 14px 32px;
    font-weight: 900;
    font-size: .85rem;
    text-transform: uppercase;
