/* =========================================
   1. VARIABLES Y BASE
   ========================================= */
:root {
    --zarco-blue: #0A2240; 
    --zarco-blue-light: #16365C; 
    --zarco-blue-glass: rgba(10, 34, 64, 0.95); 
    --zarco-red: #A81200; 
    --zarco-red-dark: #7A0A00; 
    --white: #FFFFFF; 
    --wa-green: #25D366; 
    --transition-fast: 0.3s cubic-bezier(0.25, 0.8, 0.25, 1);
    --expo: cubic-bezier(0.16, 1, 0.3, 1);
}

* { margin: 0; padding: 0; box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html { scroll-behavior: smooth; }
body { font-family: 'Inter', sans-serif; background-color: var(--white); color: var(--zarco-blue); overflow-x: hidden; }

.desktop-only { display: block; }
.mobile-only { display: none; }

/* REVEAL ENGINE FLUIDO */
.reveal { opacity: 0; transform: translateY(30px); transition: 1.2s var(--expo); will-change: opacity, transform; }
.reveal.active { opacity: 1; transform: translateY(0); }
.stagger-1 { transition-delay: 0.1s; } 
.stagger-2 { transition-delay: 0.2s; } 
.stagger-3 { transition-delay: 0.3s; }

/* =========================================
   2. BANNERS PRINCIPALES (SLIDERS)
   ========================================= */
.hero-slider { position: relative; width: 100%; background-color: var(--white); overflow: hidden; }
/* Margen ajustado asumiendo Navbar global */
.main-slider { margin-top: 185px; } 

.slider-wrapper { display: flex; width: 100%; transition: transform 0.8s var(--expo); }
.slide { flex: 0 0 100%; min-width: 100%; position: relative; display: block; }
.slide picture { display: block; width: 100%; height: auto; }
.slide img { width: 100%; height: auto; display: block; object-fit: cover; }

.slider-arrow { position: absolute; top: 50%; transform: translateY(-50%); background: rgba(10, 34, 64, 0.3); backdrop-filter: blur(8px); border: 1px solid rgba(255,255,255,0.2); color: var(--white); width: 50px; height: 50px; font-size: 20px; cursor: pointer; border-radius: 50%; display: flex; align-items: center; justify-content: center; z-index: 10; transition: all var(--transition-fast); }
.slider-arrow:hover { background: var(--zarco-blue); transform: translateY(-50%) scale(1.1); }
.slider-arrow.prev { left: 30px; }
.slider-arrow.next { right: 30px; }
.slider-dots { position: absolute; bottom: 20px; width: 100%; display: flex; justify-content: center; gap: 10px; z-index: 10; }
.dot { width: 10px; height: 10px; background: rgba(255, 255, 255, 0.5); border: 2px solid var(--white); border-radius: 50%; cursor: pointer; transition: all var(--transition-fast); }
.dot.active { background: var(--zarco-red); border-color: var(--zarco-red); transform: scale(1.3); }

